package platformdb

import (
	"context"
	"fmt"
	"time"
)

const migrationV1 = "\nCREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);\nCREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);\nCREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);\nCREATE INDEX IF NOT EXISTS idx_sessions_user_expiry ON sessions(user_id, expires_at);\nCREATE TABLE IF NOT EXISTS hubs(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity > 0), version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);\nCREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY, asset_no TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, hub_id TEXT NOT NULL REFERENCES hubs(id), status TEXT NOT NULL, capabilities TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);\nCREATE INDEX IF NOT EXISTS idx_assets_hub_status ON assets(hub_id, status);\nCREATE TABLE IF NOT EXISTS missions(id TEXT PRIMARY KEY, business_no TEXT NOT NULL UNIQUE, hub_id TEXT NOT NULL REFERENCES hubs(id), asset_id TEXT REFERENCES assets(id), route_code TEXT NOT NULL, payload_units INTEGER NOT NULL CHECK(payload_units > 0), status TEXT NOT NULL, version INTEGER NOT NULL, requested_by TEXT NOT NULL REFERENCES users(id), due_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);\nCREATE INDEX IF NOT EXISTS idx_missions_hub_status_due ON missions(hub_id, status, due_at);\nCREATE TABLE IF NOT EXISTS inspections(id TEXT PRIMARY KEY, inspection_no TEXT NOT NULL UNIQUE, hub_id TEXT NOT NULL REFERENCES hubs(id), asset_id TEXT REFERENCES assets(id), target_kind TEXT NOT NULL DEFAULT 'infrastructure', target_ref TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'medium', evidence TEXT NOT NULL DEFAULT '', status TEXT NOT NULL, version INTEGER NOT NULL, requested_by TEXT NOT NULL REFERENCES users(id), due_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);\nCREATE INDEX IF NOT EXISTS idx_inspections_status_due ON inspections(status, due_at);\nCREATE TABLE IF NOT EXISTS transfer_plans(id TEXT PRIMARY KEY, plan_no TEXT NOT NULL UNIQUE, origin_hub_id TEXT NOT NULL REFERENCES hubs(id), destination_hub_id TEXT NOT NULL REFERENCES hubs(id), mode_chain TEXT NOT NULL, connection_at TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL, requested_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);\nCREATE INDEX IF NOT EXISTS idx_transfer_connection ON transfer_plans(status, connection_at);\nCREATE TABLE IF NOT EXISTS sorting_waves(id TEXT PRIMARY KEY, wave_no TEXT NOT NULL UNIQUE, hub_id TEXT NOT NULL REFERENCES hubs(id), chute_code TEXT, expected_items INTEGER NOT NULL CHECK(expected_items > 0), processed_items INTEGER NOT NULL DEFAULT 0, rejected_items INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, version INTEGER NOT NULL, requested_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);\nCREATE INDEX IF NOT EXISTS idx_sorting_hub_status ON sorting_waves(hub_id, status);\nCREATE TABLE IF NOT EXISTS incidents(id TEXT PRIMARY KEY, incident_no TEXT NOT NULL UNIQUE, hub_id TEXT NOT NULL REFERENCES hubs(id), source TEXT NOT NULL DEFAULT 'sensor', category TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'medium', assigned_to TEXT, evidence TEXT NOT NULL DEFAULT '', status TEXT NOT NULL, version INTEGER NOT NULL, requested_by TEXT NOT NULL REFERENCES users(id), due_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);\nCREATE INDEX IF NOT EXISTS idx_incidents_severity_status ON incidents(severity, status, due_at);\nCREATE TABLE IF NOT EXISTS resource_reservations(id TEXT PRIMARY KEY, resource_type TEXT NOT NULL, resource_key TEXT NOT NULL, owner_type TEXT NOT NULL, owner_id TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);\nCREATE INDEX IF NOT EXISTS idx_reservations_resource_window ON resource_reservations(resource_type, resource_key, starts_at, ends_at, status);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_reservations_active_exact_window ON resource_reservations(resource_type,resource_key,starts_at,ends_at) WHERE status='active';\nCREATE TABLE IF NOT EXISTS idempotency_records(scope TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, response_json TEXT NOT NULL, status_code INTEGER NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(scope, idempotency_key));\nCREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id TEXT NOT NULL, action TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, outcome TEXT NOT NULL, request_id TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);\nCREATE INDEX IF NOT EXISTS idx_audit_object ON audit_events(object_type, object_id, created_at DESC);\nCREATE TABLE IF NOT EXISTS outbox_events(id INTEGER PRIMARY KEY AUTOINCREMENT, topic TEXT NOT NULL, aggregate_type TEXT NOT NULL, aggregate_id TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL, next_attempt_at TEXT NOT NULL, created_at TEXT NOT NULL, published_at TEXT);\nCREATE INDEX IF NOT EXISTS idx_outbox_pending ON outbox_events(status, next_attempt_at);\nCREATE TABLE IF NOT EXISTS worker_jobs(id TEXT PRIMARY KEY, kind TEXT NOT NULL, object_id TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL, max_attempts INTEGER NOT NULL, next_attempt_at TEXT NOT NULL, lease_owner TEXT, lease_until TEXT, last_error TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(kind, object_id));\nCREATE INDEX IF NOT EXISTS idx_worker_due ON worker_jobs(status, next_attempt_at);\n"

func (d *DB) Migrate(ctx context.Context) error {
	if _, err := d.SQL.ExecContext(ctx, migrationV1); err != nil {
		return fmt.Errorf("apply migration v1: %w", err)
	}
	if _, err := d.SQL.ExecContext(ctx, "INSERT OR IGNORE INTO schema_migrations(version, applied_at) VALUES(1, ?)", time.Now().UTC().Format(time.RFC3339Nano)); err != nil {
		return fmt.Errorf("record migration v1: %w", err)
	}
	if err := d.migrateExtensions(ctx); err != nil {
		return err
	}
	return nil
}
